CREATE TABLE IF NOT EXISTS notes (
  id         TEXT PRIMARY KEY,
  type       TEXT NOT NULL DEFAULT 'general',
  title      TEXT,
  content    TEXT NOT NULL DEFAULT '',
  verse_ref  TEXT,
  color      TEXT NOT NULL DEFAULT 'blue',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  tags       TEXT NOT NULL DEFAULT '[]'
);
CREATE INDEX IF NOT EXISTS idx_notes_verse ON notes(verse_ref);
CREATE INDEX IF NOT EXISTS idx_notes_updated ON notes(updated_at DESC);

CREATE TABLE IF NOT EXISTS highlights (
  id         TEXT PRIMARY KEY,
  text_id    TEXT NOT NULL,
  book_id    TEXT NOT NULL,
  chapter    INTEGER NOT NULL,
  verse_num  INTEGER NOT NULL,
  start_word INTEGER,
  end_word   INTEGER,
  color      TEXT NOT NULL,
  label      TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_highlights_verse ON highlights(text_id, book_id, chapter, verse_num);

CREATE TABLE IF NOT EXISTS settings (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS workspaces (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  layout_json TEXT NOT NULL,
  created_at  INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS youtube_videos (
  video_id       TEXT PRIMARY KEY,
  title          TEXT NOT NULL,
  published      TEXT NOT NULL,
  channel_name   TEXT NOT NULL,
  channel_handle TEXT NOT NULL,
  thumbnail_url  TEXT NOT NULL,
  type           TEXT NOT NULL,
  is_live_now    INTEGER NOT NULL DEFAULT 0,
  fetched_at     TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_yt_handle   ON youtube_videos(channel_handle);
CREATE INDEX IF NOT EXISTS idx_yt_published ON youtube_videos(published DESC);

CREATE TABLE IF NOT EXISTS youtube_sync (
  channel_handle TEXT PRIMARY KEY,
  last_full_sync TEXT,
  last_refresh   TEXT
);

CREATE TABLE IF NOT EXISTS note_folders (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  parent_id  TEXT,
  created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_note_folders_parent ON note_folders(parent_id);

CREATE TABLE IF NOT EXISTS note_versions (
  id         TEXT PRIMARY KEY,
  note_id    TEXT NOT NULL,
  title      TEXT,
  content    TEXT NOT NULL DEFAULT '',
  kind       TEXT NOT NULL DEFAULT 'auto',
  created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_note_versions_note ON note_versions(note_id, created_at DESC);

-- Transcript metadata (one row per video)
CREATE TABLE IF NOT EXISTS youtube_transcripts (
  video_id      TEXT PRIMARY KEY,
  lang          TEXT NOT NULL DEFAULT 'en',
  source        TEXT NOT NULL DEFAULT 'timedtext',
  fetched_at    INTEGER NOT NULL,
  segment_count INTEGER NOT NULL DEFAULT 0,
  duration_ms   INTEGER NOT NULL DEFAULT 0,
  error         TEXT
);
CREATE INDEX IF NOT EXISTS idx_yt_transcripts_fetched
  ON youtube_transcripts(fetched_at DESC);

-- Individual caption cues
CREATE TABLE IF NOT EXISTS youtube_transcript_segments (
  id       INTEGER PRIMARY KEY,
  video_id TEXT NOT NULL
    REFERENCES youtube_transcripts(video_id) ON DELETE CASCADE,
  start_ms INTEGER NOT NULL,
  dur_ms   INTEGER NOT NULL DEFAULT 0,
  text     TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_yt_seg_video
  ON youtube_transcript_segments(video_id, start_ms);

-- FTS5 content-table (index only; triggers keep in sync with segments)
CREATE VIRTUAL TABLE IF NOT EXISTS youtube_transcripts_fts USING fts5(
  text,
  content='youtube_transcript_segments',
  content_rowid='id',
  tokenize='unicode61'
);

-- Keep FTS5 in sync with segment rows
CREATE TRIGGER IF NOT EXISTS yt_seg_ai
AFTER INSERT ON youtube_transcript_segments BEGIN
  INSERT INTO youtube_transcripts_fts(rowid, text)
  VALUES (new.id, new.text);
END;

CREATE TRIGGER IF NOT EXISTS yt_seg_ad
AFTER DELETE ON youtube_transcript_segments BEGIN
  INSERT INTO youtube_transcripts_fts(youtube_transcripts_fts, rowid, text)
  VALUES ('delete', old.id, old.text);
END;

CREATE TRIGGER IF NOT EXISTS yt_seg_au
AFTER UPDATE ON youtube_transcript_segments BEGIN
  INSERT INTO youtube_transcripts_fts(youtube_transcripts_fts, rowid, text)
  VALUES ('delete', old.id, old.text);
  INSERT INTO youtube_transcripts_fts(rowid, text)
  VALUES (new.id, new.text);
END;

CREATE VIRTUAL TABLE IF NOT EXISTS notes_fts USING fts5(
  title,
  content,
  content='notes',
  content_rowid='rowid',
  tokenize='unicode61'
);

CREATE TRIGGER IF NOT EXISTS notes_ai
AFTER INSERT ON notes BEGIN
  INSERT INTO notes_fts(rowid, title, content)
  VALUES (new.rowid, new.title, new.content);
END;

CREATE TRIGGER IF NOT EXISTS notes_ad
AFTER DELETE ON notes BEGIN
  INSERT INTO notes_fts(notes_fts, rowid, title, content)
  VALUES ('delete', old.rowid, old.title, old.content);
END;

CREATE TRIGGER IF NOT EXISTS notes_au
AFTER UPDATE ON notes BEGIN
  INSERT INTO notes_fts(notes_fts, rowid, title, content)
  VALUES ('delete', old.rowid, old.title, old.content);
  INSERT INTO notes_fts(rowid, title, content)
  VALUES (new.rowid, new.title, new.content);
END;

CREATE TABLE IF NOT EXISTS ai_chats (
  id         TEXT PRIMARY KEY,
  title      TEXT NOT NULL,
  messages   TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ai_chats_updated ON ai_chats(updated_at DESC);

CREATE TABLE IF NOT EXISTS note_heading_collapse (
  note_id     TEXT NOT NULL,
  heading_key TEXT NOT NULL,
  collapsed   INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (note_id, heading_key)
);

CREATE TABLE IF NOT EXISTS note_thread_collapse (
  note_id    TEXT NOT NULL,
  thread_key TEXT NOT NULL,
  collapsed  INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (note_id, thread_key)
);

CREATE TABLE IF NOT EXISTS verse_tags (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  color      TEXT,
  sort_order INTEGER,
  created_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_verse_tags_name ON verse_tags(name COLLATE NOCASE);

CREATE TABLE IF NOT EXISTS verse_tag_members (
  id         TEXT PRIMARY KEY,
  tag_id     TEXT NOT NULL REFERENCES verse_tags(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL DEFAULT 'verses',
  ranges     TEXT NOT NULL,
  label      TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_vtm_tag ON verse_tag_members(tag_id);

CREATE TABLE IF NOT EXISTS verse_tag_verse (
  tag_id    TEXT NOT NULL,
  member_id TEXT NOT NULL,
  book_id   TEXT NOT NULL,
  chapter   INTEGER NOT NULL,
  verse     INTEGER NOT NULL,
  PRIMARY KEY (tag_id, book_id, chapter, verse, member_id)
);
CREATE INDEX IF NOT EXISTS idx_vtv_loc ON verse_tag_verse(book_id, chapter);
CREATE INDEX IF NOT EXISTS idx_vtv_tag ON verse_tag_verse(tag_id);

CREATE TABLE IF NOT EXISTS trail_tags (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  color      TEXT,
  sort_order INTEGER,
  created_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_trail_tags_name ON trail_tags(name COLLATE NOCASE);

CREATE TABLE IF NOT EXISTS trail_tag_members (
  tag_id           TEXT NOT NULL REFERENCES trail_tags(id) ON DELETE CASCADE,
  trail_session_id TEXT NOT NULL,
  created_at       INTEGER NOT NULL,
  PRIMARY KEY (tag_id, trail_session_id)
);
CREATE INDEX IF NOT EXISTS idx_ttm_session ON trail_tag_members(trail_session_id);

CREATE TABLE IF NOT EXISTS tag_edges (
  id            TEXT PRIMARY KEY,
  source_tag_id TEXT NOT NULL REFERENCES verse_tags(id) ON DELETE CASCADE,
  target_tag_id TEXT NOT NULL REFERENCES verse_tags(id) ON DELETE CASCADE,
  arrows        TEXT NOT NULL DEFAULT 'none',   -- 'none' | 'forward' | 'backward' | 'both'
  color         TEXT,                            -- slot index as string, or literal; NULL = neutral
  dashed        INTEGER NOT NULL DEFAULT 0,
  note          TEXT NOT NULL DEFAULT '',
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_tag_edges_pair ON tag_edges(source_tag_id, target_tag_id);
CREATE INDEX IF NOT EXISTS idx_tag_edges_src ON tag_edges(source_tag_id);
CREATE INDEX IF NOT EXISTS idx_tag_edges_tgt ON tag_edges(target_tag_id);

CREATE TABLE IF NOT EXISTS sync_state (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS sync_outbox (
  seq        INTEGER PRIMARY KEY AUTOINCREMENT,
  entity     TEXT NOT NULL,
  key        TEXT NOT NULL,
  op_json    TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sync_outbox_record ON sync_outbox(entity, key);
CREATE TABLE IF NOT EXISTS sync_record_meta (
  entity  TEXT NOT NULL,
  key     TEXT NOT NULL,
  hlc     TEXT NOT NULL,
  device  TEXT NOT NULL,
  deleted INTEGER NOT NULL DEFAULT 0,
  hash    TEXT,
  PRIMARY KEY (entity, key)
);
CREATE TABLE IF NOT EXISTS sync_applied (
  device TEXT NOT NULL,
  seq    INTEGER NOT NULL,
  PRIMARY KEY (device, seq)
);
CREATE TABLE IF NOT EXISTS sync_failed (
  device   TEXT NOT NULL,
  seq      INTEGER NOT NULL,
  error    TEXT,
  attempts INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (device, seq)
);

CREATE TABLE IF NOT EXISTS pdf_bookmarks (
  id         TEXT PRIMARY KEY,
  pdf_id     TEXT NOT NULL,
  page       INTEGER NOT NULL,
  label      TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_pdf_bookmarks_pdf ON pdf_bookmarks(pdf_id, page);
